#pragma once

#include "quantum.h"

/* Layout of the two halves.  Each argument is <hand><matrix row><matrix col>.
 * Generated by scripts/gen_firmware.py from scripts/pcbgen/layout.py, so this
 * header, the PCB and the VIAL layout can never disagree.
 *
 * 72 key positions, row by row, left half first; 5 rows x 9 columns per
 * half (10 x 9 in QMK, the right half's rows are 5..9).
 *
 *   row 0 : ENC  Esc 1 2 3 4 5 6       | 7 8 9 0 - = ` BSpc
 *   row 1 : Home Tab Q W E R T         | Y U I O P [ ] backslash
 *   row 2 : End  Caps A S D F G        | H J K L ; ' Enter
 *   row 3 : PgUp LShift Z X C V B      | B N M , . / RShift Up Del
 *   row 4 : PgDn LCtrl LWin LAlt Space | Space RAlt RCtrl Left Down Right
 */
#define LAYOUT(                                                   \
    L07, L00, L01, L02, L03, L04, L05, L06,                  \
    L17, L10, L11, L12, L13, L14, L15, L27,                  \
    L20, L21, L22, L23, L24, L25, L37, L30,                  \
    L31, L32, L33, L34, L35, L47, L40, L41,                  \
    L42, L43, R50, R51, R52, R53, R54, R55,                  \
    R56, R57, R60, R61, R62, R63, R64, R65,                  \
    R66, R67, R70, R71, R72, R73, R74, R75,                  \
    R76, R80, R81, R82, R83, R84, R85, R86,                  \
    R87, R88, R90, R91, R92, R96, R97, R98                  
) {                                                           \
    { L00, L01, L02, L03, L04, L05, L06, L07, KC_NO },       \
    { L10, L11, L12, L13, L14, L15, KC_NO, L17, KC_NO },     \
    { L20, L21, L22, L23, L24, L25, KC_NO, L27, KC_NO },     \
    { L30, L31, L32, L33, L34, L35, KC_NO, L37, KC_NO },     \
    { L40, L41, L42, L43, KC_NO, KC_NO, KC_NO, L47, KC_NO }, \
    { R50, R51, R52, R53, R54, R55, R56, R57, KC_NO },       \
    { R60, R61, R62, R63, R64, R65, R66, R67, KC_NO },       \
    { R70, R71, R72, R73, R74, R75, R76, KC_NO, KC_NO },     \
    { R80, R81, R82, R83, R84, R85, R86, R87, R88 },         \
    { R90, R91, R92, KC_NO, KC_NO, KC_NO, R96, R97, R98 }   
